import { cn } from '@/lib/utils';
import {
    Drawer,
    DrawerContent,
    DrawerTitle,
    DrawerTrigger,
} from '@/components/ui/drawer';
import { ReactNode } from 'react';
import type { WithFadeFromProps } from 'vaul';
import { useTranslations } from '@/hooks/use-translations';

// the sheet is 88dvh tall so a strip of page stays above it to tap and close, vaul measures snaps from the sheet's own top,
// so the peek sits at 0.68 to still show 56dvh (68dvh minus the 12dvh gap)
export const SHEET_PEEK = 0.68;
export const SHEET_FULL = 1;
// up to this many filters fit without scrolling, so the sheet fits its content instead of opening at the snap points
export const COMPACT_SHEET_MAX_FILTERS = 3;

export type SheetSnap = number | string | null;

interface FilterSheetProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    snap: SheetSnap;
    onSnapChange: (snap: SheetSnap) => void;
    isEditing: boolean;
    compact: boolean;
    trigger: ReactNode;
    children: ReactNode;
}

export function FilterSheet({
    open,
    onOpenChange,
    snap,
    onSnapChange,
    isEditing,
    compact,
    trigger,
    children,
}: FilterSheetProps) {
    const { trans } = useTranslations();

    const snapProps: WithFadeFromProps | Record<string, never> = compact
        ? {}
        : { snapPoints: [SHEET_PEEK, SHEET_FULL], fadeFromIndex: 0 };

    const focusSheetWithoutKeyboard = (event: Event) => {
        event.preventDefault();
        if (!isEditing) {
            (event.target as HTMLElement).focus();
        }
    };

    return (
        <Drawer
            open={open}
            onOpenChange={onOpenChange}
            {...snapProps}
            activeSnapPoint={compact ? undefined : snap}
            setActiveSnapPoint={compact ? undefined : onSnapChange}
            // at a lower snap point vaul turns every swipe on the content into a drag, so only the handle drags and the list can scroll
            handleOnly
            // vaul's keyboard repositioning adds the snap offset on top of the keyboard height and pushes the sheet off screen
            repositionInputs={false}
        >
            <DrawerTrigger asChild>{trigger}</DrawerTrigger>
            <DrawerContent
                aria-describedby={undefined}
                className={cn(
                    'data-[vaul-drawer-direction=bottom]:mt-0 data-[vaul-drawer-direction=bottom]:max-h-[88dvh]',
                    !compact && 'h-full',
                )}
                onOpenAutoFocus={focusSheetWithoutKeyboard}
            >
                {/* the filter panel shows the visible title next to its reset action */}
                <DrawerTitle className="sr-only">
                    {trans('admin.data_table.table_filters.label')}
                </DrawerTitle>
                <div
                    data-testid="filters-sheet-body"
                    // cap the panel to the visible part of the sheet minus the handle so the apply button stays on screen, and ease the cap
                    // with vaul's own slide (0.5s, same curve) so the button stays pinned to the bottom while the sheet changes snap
                    className={cn(
                        'flex min-h-0 flex-1 flex-col overflow-hidden pb-[env(safe-area-inset-bottom)] transition-[max-height] duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]',
                        compact || snap === SHEET_FULL
                            ? 'max-h-[calc(88dvh-1.625rem)]'
                            : 'max-h-[calc(56dvh-1.625rem)]',
                    )}
                >
                    {children}
                </div>
            </DrawerContent>
        </Drawer>
    );
}

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';
import { useTranslations } from '@/hooks/use-translations';
import { useState } from 'react';
import type { TableFilterEditorProps } from './types';

export function TableFiltersStatus({
    filter,
    selectedValue,
    onValueChange,
}: TableFilterEditorProps) {
    const [search, setSearch] = useState('');
    const { trans } = useTranslations();
    const {
        options,
        optionLabelKey = 'label',
        optionValueKey = 'value',
    } = filter;

    const selectedArray: string[] = selectedValue
        ? Array.isArray(selectedValue)
            ? selectedValue
            : String(selectedValue).split(',').filter(Boolean)
        : [];

    const filteredOptions = options?.filter((option) =>
        String(option[optionLabelKey])
            .toLowerCase()
            .includes(search.toLowerCase()),
    );

    const handleCheckboxChange = (checked: boolean, value: string) => {
        let updated: string[];
        if (checked) {
            updated = [...selectedArray, value];
        } else {
            updated = selectedArray.filter((v) => v !== value);
        }
        onValueChange(updated.length ? updated.join(',') : undefined);
    };

    return (
        <Popover>
            <PopoverTrigger asChild>
                <Button
                    variant="outline"
                    className="w-full justify-start pl-3 text-muted-foreground"
                >
                    {trans('admin.data_table.table_filters.choose', {
                        label: filter.label,
                    })}
                </Button>
            </PopoverTrigger>
            <PopoverContent
                id={filter.param}
                align="start"
                className="min-w-[220px] p-2"
            >
                <Input
                    placeholder={trans(
                        'admin.data_table.table_filters.search_status',
                    )}
                    className="mb-2"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
                <div className="flex flex-col">
                    {filteredOptions?.length === 0 && (
                        <span className="px-3 py-2 text-sm text-muted-foreground">
                            {trans(
                                'admin.data_table.table_filters.no_status_found',
                            )}
                        </span>
                    )}
                    {filteredOptions?.map((option, index) => (
                        <Label
                            key={`${option[optionValueKey]}-${index}`}
                            className={cn(
                                'flex cursor-pointer items-center gap-2 rounded px-3 py-2 transition hover:bg-muted',
                            )}
                        >
                            <Checkbox
                                checked={selectedArray.includes(
                                    String(option[optionValueKey]),
                                )}
                                onCheckedChange={(checked) =>
                                    handleCheckboxChange(
                                        !!checked,
                                        String(option[optionValueKey]),
                                    )
                                }
                            />
                            {String(option[optionLabelKey])}
                        </Label>
                    ))}
                </div>
            </PopoverContent>
        </Popover>
    );
}

import { useTranslations } from '@/hooks/use-translations';
import { useIsMobile } from '@/hooks/use-mobile';
import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { FilterPanel } from '@/components/data-table/filters/filter-panel';
import { FilterIcon, FilterXIcon } from 'lucide-react';
import { FilterChips } from '@/components/data-table/filters/filter-chips';
import {
    COMPACT_SHEET_MAX_FILTERS,
    FilterSheet,
    SHEET_FULL,
    SHEET_PEEK,
    SheetSnap,
} from '@/components/data-table/filters/filter-sheet';
import { FilterPopover } from '@/components/data-table/filters/filter-popover';
import { TableFilter } from '@/components/data-table/filters/types';

export interface TableFiltersProps {
    filters?: TableFilter[];
    selectedValues: Record<string, string | undefined>; // keyed by filter.param
    onFilterChange: (param: string, value: unknown) => void;
    onClearAll: () => void;
    hasActiveFilters: boolean;
    activeFiltersCount?: number;
    showChips?: boolean;
}

function TableFiltersComponent({
    filters,
    selectedValues,
    onFilterChange,
    onClearAll,
    showChips = true,
}: TableFiltersProps) {
    const { trans } = useTranslations();
    const isMobile = useIsMobile();
    const [isOpen, setIsOpen] = useState(false);
    const [focusParam, setFocusParam] = useState<string | null>(null);
    const [sheetSnap, setSheetSnap] = useState<SheetSnap>(SHEET_PEEK);
    // edits in the panel stay a draft until Apply, so the table only reloads once
    const [draftValues, setDraftValues] = useState(selectedValues);
    const panelRef = useRef<HTMLDivElement>(null);

    const panelFilters = useMemo(
        () =>
            filters ? filters.filter((f) => f.includeInDropdown !== false) : [],
        [filters],
    );
    const activeFilters = panelFilters.filter(
        (filter) => selectedValues[filter.param],
    );

    const handleOpenChange = (open: boolean) => {
        setIsOpen(open);
        if (open) {
            setDraftValues(selectedValues);
            setSheetSnap(SHEET_PEEK);
        } else {
            setFocusParam(null);
        }
    };

    // a chip opens the panel on its own filter, and the phone sheet expands so that filter's control has room
    const openOnFilter = (param: string) => {
        setFocusParam(param);
        setDraftValues(selectedValues);
        setSheetSnap(SHEET_FULL);
        setIsOpen(true);
    };

    const handleValueChange = useCallback(
        (param: string, value: string | undefined) =>
            onFilterChange(param, value),
        [onFilterChange],
    );

    const handleDraftChange = useCallback(
        (param: string, value: string | undefined) =>
            setDraftValues((previous) => ({ ...previous, [param]: value })),
        [],
    );

    const applyDraft = () => {
        panelFilters
            .filter(
                (filter) =>
                    draftValues[filter.param] !== selectedValues[filter.param],
            )
            .forEach((filter) =>
                onFilterChange(filter.param, draftValues[filter.param]),
            );
        handleOpenChange(false);
    };

    useEffect(() => {
        if (!isOpen || focusParam === null) {
            return;
        }

        const field = panelRef.current?.querySelector<HTMLElement>(
            `[data-filter-param="${focusParam}"]`,
        );
        field?.scrollIntoView?.({ block: 'nearest' });
        field?.querySelector<HTMLElement>('input, button')?.focus();
    }, [focusParam, isOpen]);

    const trigger = (
        <Button
            variant="outline"
            className="relative h-8 font-normal"
            size="sm"
        >
            <FilterIcon className="text-muted-foreground" />
            <span>{trans('admin.data_table.table_filters.label')}</span>
            {activeFilters.length > 0 && (
                <span className="flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[0.625rem] leading-none font-medium text-primary-foreground tabular-nums">
                    {activeFilters.length}
                </span>
            )}
        </Button>
    );

    const panel = (
        <FilterPanel
            filters={panelFilters}
            selectedValues={draftValues}
            hasActiveFilters={panelFilters.some(
                (filter) => draftValues[filter.param],
            )}
            isMobile={isMobile}
            panelRef={panelRef}
            onValueChange={handleDraftChange}
            onReset={() => setDraftValues({})}
            onApply={applyDraft}
        />
    );

    return (
        // on phones the wrapper dissolves into the toolbar row: Clear goes after View at the right edge, the chips take their own line below
        <div className="flex flex-wrap items-center gap-2 max-md:contents">
            {showChips && activeFilters.length > 0 && (
                <FilterChips
                    filters={activeFilters}
                    selectedValues={selectedValues}
                    onEdit={openOnFilter}
                    onRemove={(param) => handleValueChange(param, undefined)}
                />
            )}

            {isMobile ? (
                <FilterSheet
                    open={isOpen}
                    onOpenChange={handleOpenChange}
                    snap={sheetSnap}
                    onSnapChange={setSheetSnap}
                    isEditing={focusParam !== null}
                    compact={panelFilters.length <= COMPACT_SHEET_MAX_FILTERS}
                    trigger={trigger}
                >
                    {panel}
                </FilterSheet>
            ) : (
                <FilterPopover
                    open={isOpen}
                    onOpenChange={handleOpenChange}
                    isEditing={focusParam !== null}
                    trigger={trigger}
                >
                    {panel}
                </FilterPopover>
            )}

            {activeFilters.length > 0 && (
                <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 text-muted-foreground max-md:order-1 max-md:ml-auto"
                    onClick={onClearAll}
                >
                    <FilterXIcon className="size-4" />
                    {trans('admin.data_table.table_filters.clear')}
                </Button>
            )}
        </div>
    );
}

