                            </span>
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align={isMobile ? 'center' : 'end'}>
                        {dropdownActions.map((action) => {
                            const ActionIcon = action.icon;
                            return (
                                <DropdownMenuItem
                                    key={action.id ?? action.label}
                                    onClick={action.onClick}
                                    disabled={action.disabled}
                                >
