    SelectItem,
    SelectTrigger,
    SelectValue,
} from '../ui/select';

type QueryState = {
    page?: number;
    cursor?: string | null;
    filter: Record<string, unknown>;
    sort?: string;
    pageSize?: number;
};

type TablePaginationProps = {
    links: Links;
    meta: Meta;
    setQuery: Dispatch<SetStateAction<QueryState>>;
    selectedCount?: number;
    pageSizeOptions?: number[];
    hasMultiselect?: boolean;
    defaultPageSizeOption?: number;
    pageName?: string;
};

function TablePaginationComponent({
    links,
    meta,
    setQuery,
    selectedCount = 0,
    pageSizeOptions = [20, 30, 50, 100],
    hasMultiselect = false,
    defaultPageSizeOption = 20,
    pageName = 'page',
}: TablePaginationProps) {
    const { trans, transChoice } = useTranslations();
    const isCursor = meta.nextCursor != null || meta.prevCursor != null;

    const getPageFromUrl = useCallback(
        (url: string | null | undefined): number | null => {
            if (!url) return null;
            try {
                const urlObject = new URL(url);
                const page = urlObject.searchParams.get(pageName);
                return page ? Number(page) : 1;
            } catch {
                return null;
            }
        },
        [pageName],
    );

    const handlePageChange = useCallback(
        (page: number | null) => {
            if (!page) return;
            setQuery((prev) => ({ ...prev, page, cursor: null }));
        },
        [setQuery],
    );

    const handleCursorChange = useCallback(
        (cursor: string | null) => {
            if (cursor == null) return;
            setQuery((prev) => ({ ...prev, cursor, page: undefined }));
        },
        [setQuery],
    );

    const handlePerPageChange = useCallback(
        (value: string) => {
            setQuery((prev) => ({
                ...prev,
                pageSize: Number(value),
                page: 1,
                cursor: null,
            }));
        },
        [setQuery],
    );

    const { currentPage, totalPages, perPage } = useMemo(() => {
        const resolvedPerPage = meta.perPage ?? defaultPageSizeOption;

        if (isCursor || !meta.currentPage) {
            return {
                currentPage: 1,
                totalPages: 1,
                perPage: resolvedPerPage,
            };
        }

        return {
            currentPage: meta.currentPage,
            totalPages: meta.lastPage ?? meta.currentPage ?? 1,
            perPage: resolvedPerPage,
        };
    }, [
        defaultPageSizeOption,
        isCursor,
        meta.currentPage,
        meta.lastPage,
        meta.perPage,
    ]);

    return (
        <div className="flex w-full flex-wrap items-center justify-between gap-x-4 gap-y-2 py-2 text-sm max-sm:justify-start">
            <div className="text-neutral-600 max-sm:w-full max-sm:empty:hidden">
                {hasMultiselect && (
                    <span>
                        {transChoice(
                            'admin.data_table.pagination.selected_rows',
                            selectedCount,
                            {
                                count: selectedCount,
                                total: meta.to ?? meta.total,
                            },
                        )}
                    </span>
                )}
            </div>

            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                    <span className="text-sm font-medium whitespace-nowrap">
                        {trans('admin.data_table.pagination.rows_per_page')}
                    </span>
                    <Select
                        defaultValue={String(perPage)}
                        onValueChange={handlePerPageChange}
                    >
                        <SelectTrigger className="h-8 w-18">
                            <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                            {pageSizeOptions?.map((option) => (
                                <SelectItem key={option} value={String(option)}>
                                    {option}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                </div>
            </div>

            <div className="flex items-center gap-2">
                {!isCursor ? (
                    <>
                        <span className="text-sm font-medium whitespace-nowrap">
                            {trans('admin.data_table.pagination.page_of', {
                                current: currentPage,
                                total: totalPages,
                            })}
                        </span>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            aria-label={trans(
                                'admin.data_table.pagination.first_page',
                            )}
                            onClick={() => handlePageChange(1)}
                            disabled={currentPage === 1}
                        >
                            <ChevronsLeft className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            aria-label={trans(
                                'admin.data_table.pagination.previous_page',
                            )}
                            onClick={() =>
                                handlePageChange(getPageFromUrl(links.prev))
                            }
                            disabled={!links.prev}
                        >
                            <ChevronLeft className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            aria-label={trans(
                                'admin.data_table.pagination.next_page',
                            )}
                            onClick={() =>
                                handlePageChange(getPageFromUrl(links.next))
                            }
                            disabled={!links.next}
                        >
                            <ChevronRight className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            aria-label={trans(
                                'admin.data_table.pagination.last_page',
                            )}
                            onClick={() => handlePageChange(totalPages)}
                            disabled={currentPage === totalPages}
                        >
                            <ChevronsRight className="h-4 w-4" />
                        </Button>
                    </>
                ) : (
                    <>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            aria-label={trans(
                                'admin.data_table.pagination.previous_page',
                            )}
                            onClick={() =>
                                handleCursorChange(meta.prevCursor ?? null)
                            }
                            disabled={!meta.prevCursor}
                        >
                            <ChevronLeft className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            aria-label={trans(
                                'admin.data_table.pagination.next_page',
                            )}
                            onClick={() =>
                                handleCursorChange(meta.nextCursor ?? null)
                            }
                            disabled={!meta.nextCursor}
                        >
                            <ChevronRight className="h-4 w-4" />
                        </Button>
                    </>
                )}
            </div>
        </div>
    );
}

export const TablePagination = memo(TablePaginationComponent);

TablePagination.displayName = 'TablePagination';

import { Input } from '@/components/ui/input';
import { useSyncedDraft } from '@/hooks/use-synced-draft';
import { Search } from 'lucide-react';
import debounce from 'lodash-es/debounce';
import { useEffect, useMemo } from 'react';

export interface TableSearchInputProps {
    value: string;
    onDebouncedChange: (value: string) => void;
    placeholder: string;
    debounceMs?: number;
}

const identity = (value: string): string => value;

export function TableSearchInput({
    value,
    onDebouncedChange,
    placeholder,
    debounceMs = 400,
}: TableSearchInputProps) {
    const [inputValue, setInputValue] = useSyncedDraft(value, identity);
    const emitChange = useMemo(
        () => debounce(onDebouncedChange, debounceMs),
        [debounceMs, onDebouncedChange],
    );

    useEffect(() => {
        return () => emitChange.cancel();
    }, [emitChange]);

    const handleChange = (nextValue: string) => {
        setInputValue(nextValue);
        emitChange(nextValue);
    };

    return (
        <div className="relative max-w-md min-w-48 flex-1">
            <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-neutral-400" />
            <Input
                placeholder={placeholder}
                value={inputValue}
                onChange={(event) => handleChange(event.target.value)}
                className="pl-10 md:max-w-62.5 lg:max-w-sm"
                type="search"
            />
        </div>
    );
}

import { Button } from '@/components/ui/button';
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from '@/components/ui/command';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';
import { useTranslations } from '@/hooks/use-translations';
import { Column, Table } from '@tanstack/react-table';
import { Check, Settings2 } from 'lucide-react';
import { ComponentProps } from 'react';

interface TableViewColumns<TData> extends ComponentProps<
    typeof PopoverContent
> {
    table: Table<TData>;
    disabled?: boolean;
}

function getColumnLabel<TData>(column: Column<TData>): string {
    if (typeof column.columnDef.header === 'string') {
        return column.columnDef.header;
    }

    const meta = column.columnDef.meta as { title?: string } | undefined;

    return meta?.title ?? column.id;
}

export function TableViewColumns<TData>({
    table,
    disabled,
    ...props
}: TableViewColumns<TData>) {
    const columnVisibility = table.getState().columnVisibility;
    const toggleableColumns = table
        .getAllColumns()
        .filter((column) => column.getCanHide());
    const visibleColumnsCount = toggleableColumns.filter((column) =>
        column.getIsVisible(),
    ).length;
    const columnsCount = toggleableColumns.length;
    const { trans } = useTranslations();
    return (
        <Popover>
            <PopoverTrigger asChild>
                <Button
                    aria-label="Toggle columns"
                    role="combobox"
                    variant="outline"
                    size="sm"
                    className="ml-auto flex h-8 font-normal"
                    disabled={disabled}
                >
                    <Settings2 className="text-muted-foreground" />
                    {trans('admin.data_table.view_columns.view')}
                    <span className="text-muted-foreground">
                        {visibleColumnsCount}/{columnsCount}
                    </span>
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-60 p-0" {...props} align={'end'}>
                <Command>
                    <CommandInput placeholder="Search columns..." />
                    <CommandList>
                        <CommandEmpty>No columns found.</CommandEmpty>
                        <CommandGroup>
                            {toggleableColumns.map((column) => (
                                <CommandItem
                                    key={`${column.id}-${columnVisibility?.[column.id] ? 'visible' : 'hidden'}`}
                                    onSelect={() =>
                                        column.toggleVisibility(
                                            !column.getIsVisible(),
                                        )
                                    }
                                >
                                    <span className="truncate">
                                        {getColumnLabel(column)}
                                    </span>
                                    <span className="ml-auto flex size-4 items-center justify-center">
                                        {column.getIsVisible() ? (
                                            <Check className="size-4 text-muted-foreground" />
                                        ) : null}
                                    </span>
                                </CommandItem>
                            ))}
                        </CommandGroup>
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    );
}

import { router, usePage } from '@inertiajs/react';
import { SortingState } from '@tanstack/react-table';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

export type TableVisitOptions = NonNullable<Parameters<typeof router.get>[2]>;
type QueryParamValue = string | number | boolean;

export type Query = {
    page?: number;
    cursor?: string | null;
    pageSize?: number;
    sort?: string;
    filter: Record<string, unknown>;
};

// Extract URL parsing to avoid recreation
const parseInitialQuery = (
    filterParams?: string[],
    pageName = 'page',
    pageSizeName = 'pageSize',
    sortName = 'sort',
    defaultSort?: string,
    currentUrl = '/',
): Query => {
    const searchParams = new URL(currentUrl, 'http://localhost').searchParams;
    const initial: Query = { filter: {} };

    if (searchParams.has(pageName))
        initial.page = Number(searchParams.get(pageName));
    if (searchParams.has('cursor')) {
        initial.cursor = searchParams.get('cursor');
        initial.page = undefined;
    }
    if (searchParams.has(pageSizeName))
        initial.pageSize = Number(searchParams.get(pageSizeName));
    if (searchParams.has(sortName)) {
        initial.sort = searchParams.get(sortName) || undefined;
    } else if (defaultSort) {
        initial.sort = defaultSort;
    }

    filterParams?.forEach((param) => {
        const key = `filter[${param}]`;
        if (searchParams.has(key)) {
            initial.filter[param] = searchParams.get(key) as string;
        }
    });

    return initial;
};

// Extract sorting state parsing
const parseSortingFromQuery = (sort?: string): SortingState => {
    if (!sort) return [];
    const desc = sort.startsWith('-');
    const id = desc ? sort.slice(1) : sort;
    return [{ id, desc }];
};

const areSortingStatesEqual = (a?: SortingState, b?: SortingState): boolean => {
    if (!a?.length && !b?.length) {
        return true;
    }

    if (!a || !b) {
        return false;
    }

    if (a.length !== b.length) {
        return false;
    }

    return a.every((item, index) => {
        const other = b[index];
        return !!other && item.id === other.id && item.desc === other.desc;
    });
};

export function useTableQueryState(
    filterParams?: string[],
    pageName = 'page',
    pageSizeName = 'pageSize',
    sortName = 'sort',
    defaultSort?: string,
    visitOptions?: TableVisitOptions,
) {
    const currentUrl = usePage().url;

    // Memoize filter params to prevent unnecessary recalculations
    const stableFilterParams = useMemo(
        () => filterParams ?? [],
        [filterParams],
    );

    // Initialize state only once
    const [query, setQuery] = useState<Query>(() =>
        parseInitialQuery(
            stableFilterParams,
            pageName,
            pageSizeName,
            sortName,
            defaultSort,
            currentUrl,
        ),
    );
    const [sorting, setSortingState] = useState<SortingState>(() =>
        parseSortingFromQuery(query.sort),
    );

    const isFirst = useRef(true);

    const routerTimeoutRef = useRef<number | null>(null);

    const updateRouter = useCallback(
        (queryState: Query) => {
            const params: Record<string, QueryParamValue> = {};
            const currentSearchParams = new URLSearchParams(
                window.location.search,
            );

            currentSearchParams.forEach((value, key) => {
                params[key] = value;
            });

            delete params.cursor;
            delete params[pageName];
            delete params[pageSizeName];
            delete params[sortName];

            stableFilterParams.forEach((param) => {
                delete params[`filter[${param}]`];
            });

            if (queryState.cursor) {
                params.cursor = queryState.cursor;
            } else if (queryState.page && queryState.page > 1) {
                params[pageName] = queryState.page;
            }

            if (queryState.pageSize) {
                params[pageSizeName] = queryState.pageSize;
            }

            if (queryState.sort) {
                params[sortName] = queryState.sort;
            }

            Object.entries(queryState.filter).forEach(([key, value]) => {
                if (
                    (typeof value === 'string' && value !== '') ||
                    typeof value === 'number' ||
                    typeof value === 'boolean'
                ) {
                    params[`filter[${key}]`] = value;
                }
            });

            const nextSearchParams = new URLSearchParams();

            Object.entries(params).forEach(([key, value]) => {
                if (value !== undefined && value !== null) {
                    nextSearchParams.set(key, String(value));
                }
            });

            if (
                currentSearchParams.toString() === nextSearchParams.toString()
            ) {
                return;
            }

            router.get(window.location.pathname, params, {
                preserveState: true,
                preserveScroll: true,
                replace: true,
                ...visitOptions,
            });
        },
        [pageName, pageSizeName, stableFilterParams, sortName, visitOptions],
    );

    // Effect with debounced router updates
    useEffect(() => {
        if (isFirst.current) {
            isFirst.current = false;
            return;
        }

        if (routerTimeoutRef.current) {
            clearTimeout(routerTimeoutRef.current);
        }

        routerTimeoutRef.current = window.setTimeout(() => {
            updateRouter(query);
            routerTimeoutRef.current = null;
        }, 150);

        // Cleanup timeout on unmount
        return () => {
            if (routerTimeoutRef.current) {
                clearTimeout(routerTimeoutRef.current);
                routerTimeoutRef.current = null;
            }
        };
    }, [query, updateRouter]);

    const handleSortingChange = useCallback(
        (updater: SortingState | ((old: SortingState) => SortingState)) => {
            const next =
                typeof updater === 'function' ? updater(sorting) : updater;

            if (areSortingStatesEqual(next, sorting)) {
                return;
            }

            setSortingState(next);

            if (next.length) {
                const { id, desc } = next[0];
                const sortValue = desc ? `-${id}` : id;

                setQuery((prev) => ({
                    ...prev,
                    page: 1,
                    cursor: null,
                    sort: sortValue,
                }));
            } else {
                setQuery((prev) => ({
                    ...prev,
                    page: 1,
                    cursor: null,
                    sort: undefined,
                }));
            }
        },
        [setQuery, sorting],
    );
    // Optimized filter setter with shallow comparison
    const setFilter = useCallback((param: string, value: unknown) => {
        setQuery((prev) => {
            // Skip update if value hasn't changed
            if (prev.filter[param] === value) {
                return prev;
            }

            return {
                ...prev,
                page: 1,
                cursor: null,
                filter: { ...prev.filter, [param]: value },
            };
        });
    }, []);

    // Optimized clear filters
    const clearFilters = useCallback(() => {
        setQuery((prev) => {
            // Skip if already empty
            if (Object.keys(prev.filter).length === 0) {
                return prev;
            }

            return {
                ...prev,
                page: 1,
                cursor: null,
                filter: {},
            };
        });
    }, []);

    // Optimized pagination handlers
    const goToPage = useCallback((page: number | null | undefined) => {
        if (!page) return;

        setQuery((prev) => {
            if (prev.page === page) return prev; // Skip if same page
            return { ...prev, page, cursor: null };
        });
    }, []);

    const goToCursor = useCallback((cursor: string | null | undefined) => {
        if (!cursor) return;

        setQuery((prev) => {
            if (prev.cursor === cursor) return prev; // Skip if same cursor
            return { ...prev, cursor, page: undefined };
        });
    }, []);

    const setPerPage = useCallback((per: number) => {
        setQuery((prev) => {
            if (prev.pageSize === per) return prev; // Skip if same page size
            return {
                ...prev,
                pageSize: per,
                page: 1,
                cursor: null,
            };
        });
    }, []);

    return useMemo(
        () => ({
            query,
            setQuery,
            sorting,
            setSorting: handleSortingChange,
            setFilter,
            clearFilters,
            filterParams: stableFilterParams,
            goToPage,
            goToCursor,
            setPerPage,
        }),
        [
            query,
            sorting,
            handleSortingChange,
            setFilter,
            clearFilters,
            stableFilterParams,
            goToPage,
            goToCursor,
            setPerPage,
        ],
    );
}

import { Row } from '@tanstack/react-table';
import { RefObject, useEffect, useMemo, useRef, useState } from 'react';

export const VIRTUALIZATION_THRESHOLD = 40;
export const ESTIMATED_ROW_HEIGHT = 52;
export const OVERSCAN = 8;

type ScrollState = {
    offset: number;
    viewport: number;
};

export type VirtualRowsResult<TData> = {
    containerRef: RefObject<HTMLDivElement | null>;
    visibleRows: Row<TData>[];
    topPadding: number;
    bottomPadding: number;
};

export function useVirtualRows<TData>(
    rows: Row<TData>[],
    enabled: boolean,
): VirtualRowsResult<TData> {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [scrollState, setScrollState] = useState<ScrollState>({
        offset: 0,
        viewport: 0,
    });

    useEffect(() => {
        if (!enabled) {
            return;
        }

        const element = containerRef.current;
        if (!element) return;

        let animationFrame: number | null = null;

        const measure = () => {
            animationFrame = null;
            const newOffset = element.scrollTop;
            const newViewport = element.clientHeight;

            setScrollState((prev) => {
                if (
                    prev.offset === newOffset &&
                    prev.viewport === newViewport
                ) {
                    return prev;
                }
                return { offset: newOffset, viewport: newViewport };
            });
        };

        measure();

        const handleScroll = () => {
            if (animationFrame == null) {
                animationFrame = requestAnimationFrame(measure);
            }
        };

        element.addEventListener('scroll', handleScroll);
        window.addEventListener('resize', measure);

        return () => {
            if (animationFrame != null) cancelAnimationFrame(animationFrame);
            element.removeEventListener('scroll', handleScroll);
            window.removeEventListener('resize', measure);
        };
    }, [enabled, rows.length]);

    const virtualizationState = useMemo(() => {
        if (!enabled) {
            return {
                containerRef,
                visibleRows: rows,
                topPadding: 0,
                bottomPadding: 0,
            };
        }

        const { offset, viewport } = scrollState;
        const startIndex = Math.max(
            0,
            Math.floor(offset / ESTIMATED_ROW_HEIGHT) - OVERSCAN,
        );
        const endIndex = Math.min(
            rows.length,
            Math.ceil((offset + viewport) / ESTIMATED_ROW_HEIGHT) + OVERSCAN,
        );

        return {
            containerRef,
            visibleRows: rows.slice(startIndex, endIndex),
            topPadding: startIndex * ESTIMATED_ROW_HEIGHT,
            bottomPadding: Math.max(
                0,
                (rows.length - endIndex) * ESTIMATED_ROW_HEIGHT,
            ),
        };
    }, [enabled, rows, scrollState]);

    return virtualizationState;
}

import { useSyncExternalStore } from 'react';

const MOBILE_BREAKPOINT = 768;

const mql =
    typeof window === 'undefined'
        ? undefined
        : window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);

function mediaQueryListener(callback: (event: MediaQueryListEvent) => void) {
    if (!mql) {
        return () => {};
    }

    mql.addEventListener('change', callback);

    return () => {
        mql.removeEventListener('change', callback);
    };
}

function isSmallerThanBreakpoint(): boolean {
    return mql?.matches ?? false;
}

function getServerSnapshot(): boolean {
    return false;
}

export function useIsMobile(): boolean {
    return useSyncExternalStore(
        mediaQueryListener,
        isSmallerThanBreakpoint,
        getServerSnapshot,
    );
}

import {
    useEffect,
    useRef,
    useState,
    type Dispatch,
    type SetStateAction,
} from 'react';

export function useSyncedDraft<TSource, TDraft>(
    source: TSource,
    createDraft: (source: TSource) => TDraft,
): [TDraft, Dispatch<SetStateAction<TDraft>>] {
    const [draft, setDraft] = useState<TDraft>(() => createDraft(source));
    const previousSource = useRef(source);

    useEffect(() => {
        if (Object.is(previousSource.current, source)) {
            return;
        }

        previousSource.current = source;
        setDraft(createDraft(source));
    }, [createDraft, source]);

    return [draft, setDraft];
}

