        case 'ur':
        case 'ur-IN':
        case 'ur-PK':
        case 'zu':
        case 'zu-ZA':
            return number === 1 ? 0 : 1;
        case 'am':
        case 'am-ET':
        case 'bh':
        case 'fil':
