            return number % 10 == 1 && number % 100 != 11
                ? 0
                : number % 10 >= 2 &&
                    number % 10 <= 4 &&
                    (number % 100 < 10 || number % 100 >= 20)
                  ? 1
                  : 2;
        case 'cs':
        case 'cs-CZ':
        case 'sk':
        case 'sk-SK':
            return number == 1 ? 0 : number >= 2 && number <= 4 ? 1 : 2;
        case 'ga':
        case 'ga-IE':
            return number == 1 ? 0 : number == 2 ? 1 : 2;
        case 'lt':
        case 'lt-LT':
            return number % 10 == 1 && number % 100 != 11
                ? 0
                : number % 10 >= 2 && (number % 100 < 10 || number % 100 >= 20)
                  ? 1
                  : 2;
        case 'sl':
        case 'sl-SI':
            return number % 100 == 1
                ? 0
                : number % 100 == 2
                  ? 1
                  : number % 100 == 3 || number % 100 == 4
                    ? 2
                    : 3;
        case 'mk':
        case 'mk-MK':
            return number % 10 == 1 ? 0 : 1;
        case 'mt':
        case 'mt-MT':
            return number == 1
                ? 0
                : number == 0 || (number % 100 > 1 && number % 100 < 11)
                  ? 1
                  : number % 100 > 10 && number % 100 < 20
                    ? 2
                    : 3;
        case 'lv':
        case 'lv-LV':
            return number == 0
                ? 0
                : number % 10 == 1 && number % 100 != 11
                  ? 1
                  : 2;
        case 'pl':
        case 'pl-PL':
            return number == 1
                ? 0
                : number % 10 >= 2 &&
                    number % 10 <= 4 &&
                    (number % 100 < 12 || number % 100 > 14)
                  ? 1
                  : 2;
        case 'cy':
        case 'cy-GB':
            return number == 1
                ? 0
                : number == 2
                  ? 1
                  : number == 8 || number == 11
                    ? 2
                    : 3;
        case 'ro':
        case 'ro-RO':
            return number == 1
                ? 0
                : number == 0 || (number % 100 > 0 && number % 100 < 20)
                  ? 1
                  : 2;
        case 'ar':
        case 'ar-AE':
        case 'ar-BH':
        case 'ar-DZ':
        case 'ar-EG':
        case 'ar-IN':
        case 'ar-IQ':
        case 'ar-JO':
        case 'ar-KW':
        case 'ar-LB':
        case 'ar-LY':
        case 'ar-MA':
        case 'ar-OM':
        case 'ar-QA':
        case 'ar-SA':
        case 'ar-SD':
        case 'ar-SS':
        case 'ar-SY':
        case 'ar-TN':
        case 'ar-YE':
            return number == 0
                ? 0
                : number == 1
                  ? 1
                  : number == 2
                    ? 2
                    : number % 100 >= 3 && number % 100 <= 10
                      ? 3
                      : number % 100 >= 11 && number % 100 <= 99
                        ? 4
                        : 5;
        default:
            return 0;
    }
}

