import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
    Command,
    CommandEmpty,
    CommandInput,
    CommandItem,
    CommandList,
} from '@/components/ui/command';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';
import { cn } from '@/lib/utils';
import { Check, ChevronsUpDown } from 'lucide-react';
import { useMemo, useState, type ComponentProps } from 'react';

type MultiselectExpandableProps<
    TOption extends Record<string, unknown>,
> = {
    options: TOption[];
    valueKey: keyof TOption | string;
    labelKey: keyof TOption | string;
    selectedValues: string[];
    onChange: (values: string[]) => void;
    placeholder?: string;
    searchPlaceholder?: string;
    maxShownItems?: number;
    displayMode?: 'badges' | 'summary';
} & Omit<ComponentProps<typeof Button>, 'children' | 'value' | 'onChange'>;

function optionText(
    option: Record<string, unknown>,
    key: PropertyKey,
): string {
    return String(option[key as keyof typeof option]);
}

export function MultiselectExpandable<
    TOption extends Record<string, unknown>,
>({
    options,
    valueKey,
    labelKey,
    selectedValues,
    onChange,
    placeholder = 'Select options',
    searchPlaceholder = 'Search...',
    maxShownItems = 2,
    displayMode = 'badges',
    className,
    disabled,
    ...buttonProps
}: MultiselectExpandableProps<TOption>) {
    const [open, setOpen] = useState(false);
    const [searchValue, setSearchValue] = useState('');
    const selectedValueSet = useMemo(
        () => new Set(selectedValues),
        [selectedValues],
    );
    const selectedOptions = options.filter((option) =>
        selectedValueSet.has(optionText(option, valueKey)),
    );
    const filteredOptions = useMemo(() => {
        const query = searchValue.trim().toLowerCase();

        if (!query) {
            return options;
        }

        return options.filter((option) =>
            `${optionText(option, labelKey)} ${optionText(option, valueKey)}`
                .toLowerCase()
                .includes(query),
        );
    }, [labelKey, options, searchValue, valueKey]);

    const toggleValue = (value: string) => {
        onChange(
            selectedValueSet.has(value)
                ? selectedValues.filter((selectedValue) => selectedValue !== value)
                : [...selectedValues, value],
        );
    };

    const visibleOptions = selectedOptions.slice(0, maxShownItems);
    const hiddenCount = Math.max(selectedOptions.length - maxShownItems, 0);

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    type="button"
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    disabled={disabled}
                    className={cn(
                        'min-h-9 justify-between font-normal',
                        !selectedOptions.length && 'text-muted-foreground',
                        className,
                    )}
                    {...buttonProps}
                >
                    <span className="flex min-w-0 flex-1 items-center gap-1 overflow-hidden">
                        {selectedOptions.length === 0 ? (
                            <span className="truncate">{placeholder}</span>
                        ) : displayMode === 'summary' ? (
                            <span className="truncate">
                                {selectedOptions.length} selected
                            </span>
                        ) : (
                            <>
                                {visibleOptions.map((option) => (
                                    <Badge
                                        key={optionText(option, valueKey)}
                                        variant="secondary"
                                        className="max-w-32 truncate font-normal"
                                    >
                                        {optionText(option, labelKey)}
                                    </Badge>
                                ))}
                                {hiddenCount > 0 && (
                                    <Badge variant="outline">
                                        +{hiddenCount}
                                    </Badge>
                                )}
                            </>
                        )}
                    </span>
                    <ChevronsUpDown className="ml-2 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent
                align="start"
                className="w-(--radix-popover-trigger-width) p-0"
            >
                <Command shouldFilter={false}>
                    <CommandInput
                        placeholder={searchPlaceholder}
                        value={searchValue}
                        onValueChange={setSearchValue}
                    />
                    <CommandList>
                        <CommandEmpty>No options found.</CommandEmpty>
                        {filteredOptions.map((option) => {
                            const value = optionText(option, valueKey);
                            const selected = selectedValueSet.has(value);

                            return (
                                <CommandItem
                                    key={value}
                                    value={value}
                                    onSelect={() => toggleValue(value)}
                                >
                                    <Check
                                        className={cn(
                                            'mr-2',
                                            selected
                                                ? 'opacity-100'
                                                : 'opacity-0',
                                        )}
                                    />
                                    <span className="truncate">
                                        {optionText(option, labelKey)}
                                    </span>
                                </CommandItem>
                            );
                        })}
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    );
}

import {Button} from '@/components/ui/button';
import {Command, CommandEmpty, CommandInput, CommandItem, CommandList,} from '@/components/ui/command';
import {Popover, PopoverContent, PopoverTrigger,} from '@/components/ui/popover';
import {cn} from '@/lib/utils';
import {Check, ChevronsUpDown, X} from 'lucide-react';
import {type ComponentProps, useMemo, useState} from 'react';

const CLEAR_VALUE = '__searchable_select_clear__';

type SearchableSelectProps<TOption extends Record<string, unknown>> = {
    value?: string;
    onValueChange: (value: string | undefined) => void;
    options: TOption[];
    optionValue: keyof TOption | string;
    optionLabel: keyof TOption | string;
    placeholder?: string;
    searchPlaceholder?: string;
    emptyMessage?: string;
    searchValue?: string;
    onSearchChange?: (value: string) => void;
    contentClassName?: string;
    clearable?: boolean;
    clearLabel?: string;
} & Omit<ComponentProps<typeof Button>, 'children' | 'value' | 'onClick'>;

function optionText(
    option: Record<string, unknown>,
    key: PropertyKey,
): string {
    return String(option[key as keyof typeof option]);
}

export default function SearchableSelect<
    TOption extends Record<string, unknown>,
>({
      value,
      onValueChange,
      options,
      optionValue,
      optionLabel,
      placeholder = 'Select an option',
      searchPlaceholder = 'Search...',
      emptyMessage = 'No results found.',
      searchValue,
      onSearchChange,
      className,
      contentClassName,
      clearable = false,
      clearLabel = 'Clear selection',
      disabled,
      ...buttonProps
  }: SearchableSelectProps<TOption>) {
    const [open, setOpen] = useState(false);
    const [internalSearchValue, setInternalSearchValue] = useState('');
    const currentSearchValue = searchValue ?? internalSearchValue;
    const currentOption = options.find(
        (option) => optionText(option, optionValue) === value,
    );
    const filteredOptions = useMemo(() => {
        const query = currentSearchValue.trim().toLowerCase();

        if (!query) {
            return options;
        }

        return options.filter((option) =>
            `${optionText(option, optionLabel)} ${optionText(option, optionValue)}`
                .toLowerCase()
                .includes(query),
        );
    }, [currentSearchValue, optionLabel, optionValue, options]);

    const handleSearchChange = (nextValue: string) => {
        setInternalSearchValue(nextValue);
        onSearchChange?.(nextValue);
    };

    const handleOpenChange = (nextOpen: boolean) => {
        setOpen(nextOpen);

        if (!nextOpen) {
            handleSearchChange('');
        }
    };

    const handleClear = () => {
        onValueChange(undefined);
        setOpen(false);
        handleSearchChange('');
    };

    return (
        <Popover open={open} onOpenChange={handleOpenChange}>
            <div className="relative w-full">
                <PopoverTrigger asChild>
                    <Button
                        type="button"
                        variant="outline"
                        role="combobox"
                        aria-expanded={open}
                        disabled={disabled}
                        className={cn(
                            'w-full justify-between font-normal',
                            value && clearable && 'pr-16',
                            className,
                        )}
                        {...buttonProps}
                    >
                        <span
                            className={cn(
                                'truncate',
                                !currentOption && 'text-muted-foreground',
                            )}
                        >
                            {currentOption
                                ? optionText(currentOption, optionLabel)
                                : placeholder}
                        </span>
                        <ChevronsUpDown className="opacity-50" />
                    </Button>
                </PopoverTrigger>
                {value && clearable ? (
                    <Button
                        type="button"
                        variant="ghost"
                        size="icon-xs"
                        aria-label={clearLabel}
                        title={clearLabel}
                        disabled={disabled}
                        className="absolute top-1/2 right-8 z-10 -translate-y-1/2 text-muted-foreground hover:bg-transparent hover:text-foreground"
                        onPointerDown={(event) => {
                            event.stopPropagation();
                        }}
                        onClick={(event) => {
                            event.stopPropagation();
                            handleClear();
                        }}
                    >
                        <X />
                    </Button>
                ) : null}
            </div>
            <PopoverContent
                align="start"
                className={cn(
                    'w-(--radix-popover-trigger-width) p-0',
                    contentClassName,
                )}
            >
                <Command shouldFilter={false}>
                    <CommandInput
                        placeholder={searchPlaceholder}
                        value={currentSearchValue}
                        onValueChange={handleSearchChange}
                    />
                    <CommandList>
                        <CommandEmpty>{emptyMessage}</CommandEmpty>
                        {clearable ? (
                            <CommandItem
                                value={CLEAR_VALUE}
                                onSelect={handleClear}
                            >
                                {clearLabel}
                            </CommandItem>
                        ) : null}
                        {filteredOptions.map((option) => {
                            const optionValueText = optionText(
                                option,
                                optionValue,
                            );

                            return (
                                <CommandItem
                                    key={optionValueText}
                                    value={optionValueText}
                                    onSelect={() => {
                                        onValueChange(optionValueText);
                                        setOpen(false);
                                    }}
                                >
                                    <span className="truncate">
                                        {optionText(option, optionLabel)}
                                    </span>
                                    <Check
                                        className={cn(
                                            'ml-auto',
                                            value === optionValueText
                                                ? 'opacity-100'
                                                : 'opacity-0',
                                        )}
                                    />
                                </CommandItem>
                            );
                        })}
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    );
}
